// Parsear sitemap-vehicles.xml → todas las URLs de coche (1 item con el array)
const httpOut = $input.item.json;
const xml = typeof httpOut === 'string' ? httpOut : String(httpOut.data || httpOut.body || '');
// El sitemap ES el catalogo entero: sin el no hay nada que raspar, y seguir
// adelante con una lista vacia haria creer que Modrive no tiene coches.
const estado = (httpOut && typeof httpOut === 'object') ? Number(httpOut.statusCode || 0) : 200;
if (estado !== 200 || !xml) {
  throw new Error('El sitemap de Modrive devolvio HTTP ' + estado + ' — run detenido');
}
const urls = [];
const re = /<loc>(https:\/\/www\.modrive\.com\/coches-[a-z0-9-]+\/[a-z0-9-]+-(\d+)\/?)<\/loc>/g;
let m;
while ((m = re.exec(xml)) !== null) urls.push({ id: 'modrive_' + m[2], url: m[1] });
return [{ json: { urls: urls, total: urls.length } }];

// Elegir N fichas por ejecución: primero las que faltan en BD, luego las más antiguas
const N = 400;
const urls = $('Code: Extraer URLs del sitemap').first().json.urls || [];
const byId = {}; urls.forEach(function (u) { byId[u.id] = u.url; });
const existing = $input.all().map(function (i) { return i.json; }).filter(function (e) { return e && e.id; });
const has = {}; existing.forEach(function (e) { has[e.id] = true; });
const missing = urls.filter(function (u) { return !has[u.id]; });
existing.sort(function (a, b) { return (Number(a.upd) || 0) - (Number(b.upd) || 0); });
const stale = existing.filter(function (e) { return byId[e.id]; }).map(function (e) { return { url: byId[e.id] }; });
const pick = missing.map(function (u) { return { url: u.url }; }).concat(stale).slice(0, N);
return pick.map(function (p) { return { json: { url: p.url } }; });

// Modrive – transform: ficha HTML → JSON-LD Vehicle → UPSERT en moveadvisor_marketplace_vo_offers
const httpOut = $input.item.json;
const html = typeof httpOut === 'string' ? httpOut : String(httpOut.data || httpOut.body || '');
// Una ficha que no viene bien se salta y ya. Aqui NO se lanza el error: una
// sola mala no puede tumbar las otras cuatrocientas de la pasada. El corte de
// conexion llega con codigo 0 gracias a onError en el nodo HTTP.
const estado = (httpOut && typeof httpOut === 'object') ? Number(httpOut.statusCode || 0) : 200;
if (estado !== 200) {
  console.log('[modrive] ficha con HTTP ' + estado + ', se salta');
  return [{ json: { sql: null } }];
}

function esc(v) {
  if (v === null || v === undefined || v === '') return 'NULL';
  if (typeof v === 'number') return isNaN(v) ? 'NULL' : String(v);
  return "'" + String(v).replace(/'/g, "''") + "'";
}
function normFuel(s) {
  s = String(s || '').toLowerCase();
  if (s.indexOf('electric') !== -1 && (s.indexOf('/') !== -1 || s.indexOf('hybrid') !== -1)) return 'Híbrido';
  if (s.indexOf('electric') !== -1 || s.indexOf('eléctric') !== -1) return 'Eléctrico';
  if (s.indexOf('hybrid') !== -1 || s.indexOf('híbrido') !== -1) return 'Híbrido';
  if (s.indexOf('diesel') !== -1 || s.indexOf('diésel') !== -1) return 'Diesel';
  if (s.indexOf('gasolin') !== -1 || s.indexOf('petrol') !== -1 || s.indexOf('gasoline') !== -1) return 'Gasolina';
  if (s.indexOf('glp') !== -1 || s.indexOf('lpg') !== -1 || s.indexOf('gas') !== -1) return 'Gas';
  return '';
}
function num(s) { const n = parseInt(String(s).replace(/[^\d]/g, ''), 10); return isNaN(n) ? null : n; }

// extraer el Vehicle del JSON-LD
let v = null;
const blocks = [...html.matchAll(/<script[^>]*type="application\/ld\+json"[^>]*>([\s\S]*?)<\/script>/g)];
for (const b of blocks) {
  let o; try { o = JSON.parse(b[1]); } catch (e) { continue; }
  const arr = o['@graph'] || (Array.isArray(o) ? o : [o]);
  const find = (x) => { if (!x || typeof x !== 'object') return null; if (x['@type'] === 'Vehicle' || x['@type'] === 'Car') return x; for (const k in x) { const r = find(x[k]); if (r) return r; } return null; };
  v = find(arr);
  if (v) break;
}
if (!v) return [{ json: { sql: null, count: 0 } }];

// La URL buena es la que hemos PEDIDO, que sale del sitemap, no la que anuncia
// el JSON-LD de la ficha.
//
// Modrive cambio sus rutas de /coches-segunda-mano/ a /coches-ocasion/ y su
// sitemap ya publica las nuevas, pero el JSON-LD de dentro de la ficha sigue
// diciendo la vieja. Fiandose de el, el scraper guardaba URLs que redirigen: el
// 2026-09-08 metio 210 ofertas nuevas con la ruta rota, el mismo dia en que se
// habian reparado a mano las otras 1.788.
//
// El sitemap es la fuente autorizada de este scraper; la ficha solo aporta los
// datos del coche. El numero final es el mismo en las dos, asi que el id no
// cambia.
const urlPedida = String(($('Loop: ficha por ficha').item.json || {}).url || '');
const url = urlPedida || (v.offers && v.offers.url) || v.url || v['@id'] || '';
const idm = String(url).match(/-(\d+)\/?$/);
const id = idm ? ('modrive_' + idm[1]) : null;
// El JSON-LD de Modrive publica como precio EL DE FINANCIAR SIN ENTRADA, no el
// de contado. La ficha los ensena separados:
//
//     Precio al contado                     17.500 EUR
//     Financia sin entrada                  16.000 EUR
//     Descuento por financiar sin entrada   -1.500 EUR
//
// Se miraron 12 fichas al azar el 2026-09-08 y en las 12 el precio del JSON-LD
// era el financiado, entre 1.000 y 2.862 EUR por debajo del de contado. O sea
// que el escaparate ensenaba las 1.988 de Modrive mas baratas de lo que
// cuestan, y compitiendo contra Gamboa, VIAN, Wallapop y Milanuncios, que
// publican precio de venta sin condiciones.
//
// `price` es el de contado, que es el comparable y el que ve el cliente. El
// financiado no se tira: se guarda en price_financed.
const precioFinanciado = v.offers && v.offers.price ? num(v.offers.price) : null;
let precioContado = null;
const mcont = html.match(/Precio al contado[\s\S]{0,200}?<span[^>]*>\s*([\d.]+)\s*(?:\u20ac|&euro;)/);
if (mcont) precioContado = num(mcont[1]);
// Si la ficha no trae el de contado nos quedamos con el del JSON-LD: es peor,
// pero perder la oferta entera es peor todavia.
if (precioContado === null && precioFinanciado !== null) {
  console.log('[modrive] ' + id + ': sin precio al contado en la ficha, se usa el del JSON-LD');
}
const price = precioContado !== null ? precioContado : precioFinanciado;
if (!id || price === null) return [{ json: { sql: null, count: 0 } }];

const brand = (v.brand && (v.brand.name || v.brand)) || '';
const model = v.model || '';
const title = (v.name || (brand + ' ' + model)).replace(/\s+/g, ' ').trim();
const version = v.vehicleConfiguration ? String(v.vehicleConfiguration).split(',')[0].trim() : '';
const year = (v.productionDate && String(v.productionDate).match(/(\d{4})/)) ? String(v.productionDate).match(/(\d{4})/)[1] : null;
const mileage = v.mileageFromOdometer ? num(v.mileageFromOdometer.value != null ? v.mileageFromOdometer.value : v.mileageFromOdometer) : null;
const fuel = normFuel(v.fuelType || (v.vehicleEngine && v.vehicleEngine.engineType));
const transmission = /manual/i.test(v.vehicleTransmission || '') ? 'Manual' : (/autom/i.test(v.vehicleTransmission || '') ? 'Automatica' : '');
let powerVal = null;
if (v.vehicleEngine && v.vehicleEngine.enginePower && v.vehicleEngine.enginePower.value) powerVal = num(v.vehicleEngine.enginePower.value);
const power = powerVal ? (powerVal + ' CV') : null;
const bodyType = v.bodyType || '';
const doors = (v.numberOfDoors != null) ? parseInt(v.numberOfDoors, 10) : null;
const color = v.color || '';
const imgs = Array.isArray(v.image) ? v.image.filter(Boolean).slice(0, 15) : (v.image ? [v.image] : []);
const imageUrl = imgs[0] || '';
const imagesJson = JSON.stringify(imgs).replace(/'/g, "''");
const condition = (mileage !== null && mileage < 1000) ? 'nuevo' : 'usado';

const cols = 'id, title, brand, model, version, price, price_financed, year, mileage, fuel, power, transmission, ' +
  'color, image_url, image_urls, source_url, vehicle_condition, seller_type, portal, seller, ' +
  'available_for_purchase, is_active, created_at, updated_at';

const vals = '(' +
  esc(id) + ', ' + esc(title) + ', ' + esc(brand) + ', ' + esc(model) + ', ' + esc(version) + ', ' +
  price + ', ' + (precioFinanciado !== null ? precioFinanciado : 'NULL') + ', ' + (year || 'NULL') + ', ' + (mileage !== null ? mileage : 'NULL') + ', ' +
  esc(fuel) + ', ' + esc(power) + ', ' + esc(transmission) + ', ' +
  esc(color) + ', ' + esc(imageUrl) + ", '" + imagesJson + "', " + esc(url) + ', ' +
  esc(condition) + ", 'concesionario', 'modrive', 'Modrive', true, true, NOW(), NOW()" +
')';

// Los campos cuyo cambio SI es un cambio del anuncio. Si ninguno se mueve, lo
// unico que ha pasado es que hemos vuelto a pasar por delante.
const CAMPOS_QUE_CAMBIAN = ['title', 'price', 'price_financed', 'mileage', 'version', 'fuel',
  'power', 'transmission', 'source_url'];
const HA_CAMBIADO = CAMPOS_QUE_CAMBIAN
  .map(function (f) {
    return 'moveadvisor_marketplace_vo_offers.' + f + ' IS DISTINCT FROM EXCLUDED.' + f;
  })
  .concat(['moveadvisor_marketplace_vo_offers.is_active IS DISTINCT FROM TRUE'])
  .join(' OR ');

// updated_at NO se toca si el anuncio no ha cambiado.
//
// El escaparate ordena por portal_score y, como los tres concesionarios valen
// 80, el desempate real es updated_at DESC. Sellarlo en cada pasada pone al
// ultimo que se rasco por delante de los otros dos sin que ningun coche haya
// cambiado: paso con Gamboa el 2026-09-06 -sus 609 filas ocupaban las primeras
// 300 posiciones y el filtro de vendedor del ERP ya solo ofrecia Gamboa- y con
// VIAN el 2026-09-08, que se puso en la posicion 1 dejando a Modrive en la 746.
//
// Modrive es el que mas duele de los tres: son 1.788 ofertas, el 59% del
// escaparate. Una pasada suya sin esta condicion entierra a los otros dos.
//
// last_seen_at y last_checked_at SI se mueven siempre. Estar en el sitemap ES
// prueba de que sigue publicado, y es lo que convierte last_seen_at en la fecha
// de baja cuando el coche cae.
const onConflict = 'ON CONFLICT (id) DO UPDATE SET ' +
  'title = EXCLUDED.title, price = EXCLUDED.price, price_financed = EXCLUDED.price_financed, ' +
  'mileage = EXCLUDED.mileage, ' +
  'year = COALESCE(EXCLUDED.year, moveadvisor_marketplace_vo_offers.year), ' +
  'version = EXCLUDED.version, fuel = EXCLUDED.fuel, power = EXCLUDED.power, transmission = EXCLUDED.transmission, ' +
  "image_url = COALESCE(NULLIF(moveadvisor_marketplace_vo_offers.image_url,''), EXCLUDED.image_url), " +
  'image_urls = EXCLUDED.image_urls, vehicle_condition = EXCLUDED.vehicle_condition, ' +
  'is_active = TRUE, ' +
  'updated_at = CASE WHEN ' + HA_CAMBIADO +
    ' THEN NOW() ELSE moveadvisor_marketplace_vo_offers.updated_at END, ' +
  'last_seen_at = NOW(), last_checked_at = NOW()';

const sql = 'INSERT INTO moveadvisor_marketplace_vo_offers (' + cols + ') VALUES ' + vals + ' ' + onConflict;
return [{ json: { sql: sql, count: 1, id: id } }];
